import io
from rich.file_proxy import FileProxy
from rich.console import Console

class MockFile:
    def isatty(self):
        return True
    def write(self, text):
        pass
    def flush(self):
        pass

def test_file_proxy_isatty():
    console = Console()
    mock_file = MockFile()
    proxy = FileProxy(console, mock_file)
    print(f"Proxy isatty: {proxy.isatty()}")
    assert proxy.isatty() is True

if __name__ == "__main__":
    test_file_proxy_isatty()

